mapper.update:
UPDATE mk_journey_probe_delivery SET lease_owner = #{owner}, lease_epoch = lease_epoch + 1, lease_until = #{leaseUntil}, updated_at = #{now}
WHERE tenant_id = #{key.tenantId} AND environment_name = #{key.environment} AND cell_id = #{key.cell} AND namespace_name = #{key.namespace} AND campaign_id = #{key.campaignId} AND probe_id = #{key.probeId} AND lease_epoch = #{expectedEpoch} AND delivery_state IN ('QUEUED','RETRY')
  AND next_attempt_at <= #{now} AND expires_at > #{now} AND (lease_until IS NULL OR lease_until <= #{now})

UPDATE mk_journey_probe_delivery SET next_nonce = #{completion.nextNonce}, delivery_state = #{completion.state},
    failure_count = #{completion.failureCount}, next_attempt_at = #{completion.nextAttemptAt}, last_error_code = #{completion.errorCode},
    lease_owner = NULL, lease_until = NULL, updated_at = #{now}
WHERE tenant_id = #{key.tenantId} AND environment_name = #{key.environment} AND cell_id = #{key.cell} AND namespace_name = #{key.namespace} AND campaign_id = #{key.campaignId} AND probe_id = #{key.probeId} AND lease_owner = #{lease.owner} AND lease_epoch = #{lease.epoch}
  AND lease_until > #{now} AND delivery_state IN ('QUEUED','RETRY')

UPDATE mk_journey_probe_delivery SET delivery_state = 'EXPIRED', lease_owner = NULL, lease_until = NULL,
    last_error_code = #{errorCode}, updated_at = #{now}
WHERE environment_name = #{slot.environment} AND cell_id = #{slot.cell} AND namespace_name = #{slot.namespace} AND pending = TRUE
  AND expires_at <= #{now} AND (lease_until IS NULL OR lease_until <= #{now}) LIMIT #{limit}
